### C++:
```cpp
void removeLoop(Node* head) {
    if (!head || !head->next)
        return;

    Node* slow = head;
    Node* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;

        if (slow == fast)
            break;
    }

    if (!slow || !fast || !fast->next)
        return; // No loop found

    Node* loopStart = fast;
    Node* current = head;

    while (current != loopStart) {
        current = current->next;
        loopStart = loopStart->next;
    }

    Node* endOfLoop = current;
    while (endOfLoop->next != loopStart) {
        endOfLoop = endOfLoop->next;
    }

    endOfLoop->next = nullptr; // Remove the loop
}
```

